  { name: 'Ember', mag: 25, reserve: 125, damageBody: 16, damageHead: 100, rpm: 900, reload: 1.8, spreadStill: 0.006, spreadMove: 0.05, recoilUp: 0.007, recoilSide: 0.004, kick: 0.035, muzzle: [0.22, -0.17, -0.8] },
