      puff.cursor = (puff.cursor + 1) % PUFF_COUNT;
      positions[i * 3] = point.x + (random() - 0.5) * 0.06;
      positions[i * 3 + 1] = point.y + (random() - 0.5) * 0.06;
      positions[i * 3 + 2] = point.z + (random() - 0.5) * 0.06;
